/**
 * Golden-vector parity: the TS ActionTracker must reproduce the Python
 * tracker's output byte-for-byte on real recorded landmark sessions.
 *
 * The fixture is generated by __fixtures__/generate_golden.py under one explicit
 * driver; this test replays the SAME driver in TS and asserts equality. If this
 * fails, the port diverged from the authoritative Python tracker — fix the port,
 * do not loosen the test.
 */

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

import { ActionTracker } from "./action-tracker";
import type { PatternFrame } from "./types";

interface GoldenEvent {
  label: string;
  dx: number;
  dy: number;
  region: string;
  confidence: number;
  createdAt: number;
}

interface GoldenStep {
  i: number;
  event: GoldenEvent | null;
}

interface GoldenSession {
  name: string;
  frames: { elapsedSeconds: number; hand: number[][] | null }[];
  anchorIndex: number | null;
  steps: GoldenStep[];
  leftCount: number;
  rightCount: number;
}

const goldenPath = fileURLToPath(
  new URL("./__fixtures__/golden.json", import.meta.url),
);
const golden = JSON.parse(readFileSync(goldenPath, "utf-8")) as {
  sessions: GoldenSession[];
};

/** IEEE-754 doubles with identical op order should be bit-identical; a tiny
 * epsilon guards against any incidental platform difference without hiding a
 * real logic drift (which shows up as a wrong label/region/count). */
const EPS = 1e-9;

describe("ActionTracker parity with Python golden vectors", () => {
  for (const session of golden.sessions) {
    it(session.name, () => {
      const tracker = new ActionTracker();
      let anchorIndex: number | null = null;
      const events: (GoldenEvent | null)[] = [];

      for (let index = 0; index < session.frames.length; index += 1) {
        const frame = session.frames[index];
        const hand = frame.hand;

        if (hand === null) {
          if (anchorIndex !== null) tracker.markNoHand();
          events.push(null);
          continue;
        }

        const raw = hand.map(
          (point) => [point[0], point[1]] as const,
        ) as PatternFrame;

        if (anchorIndex === null) {
          anchorIndex = index;
          tracker.setAnchor(raw, frame.elapsedSeconds);
          events.push(null);
          continue;
        }

        const event = tracker.update(raw, frame.elapsedSeconds);
        events.push(
          event === null
            ? null
            : {
                label: event.label,
                dx: event.position.dx,
                dy: event.position.dy,
                region: event.position.region,
                confidence: event.confidence,
                createdAt: event.createdAt,
              },
        );
      }

      expect(anchorIndex).toBe(session.anchorIndex);
      expect(events.length).toBe(session.steps.length);

      for (let step = 0; step < session.steps.length; step += 1) {
        const expected = session.steps[step].event;
        const actual = events[step];
        if (expected === null) {
          expect(actual, `step ${step} should not fire`).toBeNull();
          continue;
        }
        expect(actual, `step ${step} should fire`).not.toBeNull();
        const fired = actual as GoldenEvent;
        expect(fired.label, `step ${step} label`).toBe(expected.label);
        expect(fired.region, `step ${step} region`).toBe(expected.region);
        expect(Math.abs(fired.dx - expected.dx)).toBeLessThan(EPS);
        expect(Math.abs(fired.dy - expected.dy)).toBeLessThan(EPS);
        expect(Math.abs(fired.confidence - expected.confidence)).toBeLessThan(
          EPS,
        );
        expect(fired.createdAt).toBe(expected.createdAt);
      }

      expect(tracker.leftSwipeCount).toBe(session.leftCount);
      expect(tracker.rightSwipeCount).toBe(session.rightCount);
    });
  }
});
